param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}

$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('DefaultEncodingFactories'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('probe');$builder=$module.DefineType('ArrayEncoding',[Reflection.TypeAttributes]'Public,Sealed',[Text.Encoding]);$fields=@{};foreach($name in @('Multiplier','CountMode','WriteMode')){$fields[$name]=$builder.DefineField($name,[int],[Reflection.FieldAttributes]::Public)};$fields.Trace=$builder.DefineField('Trace',[Collections.Generic.List[int[]]],[Reflection.FieldAttributes]::Public)
$constructor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@());$il=$constructor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.Encoding].GetConstructor([Reflection.BindingFlags]'Instance,NonPublic',$null,[type[]]@(),$null));$il.Emit([Reflection.Emit.OpCodes]::Ret)
foreach($abstract in [Text.Encoding].GetMethods()|Where-Object IsAbstract){[type[]]$parameters=@($abstract.GetParameters()|ForEach-Object ParameterType);$method=$builder.DefineMethod($abstract.Name,[Reflection.MethodAttributes]'Public,Virtual,HideBySig',$abstract.ReturnType,$parameters);$il=$method.GetILGenerator();$write=$abstract.Name -in @('GetBytes','GetChars');$count=$abstract.Name -in @('GetByteCount','GetCharCount');if($write -or $count){$kind=switch($abstract.Name){GetByteCount{0}GetBytes{1}GetCharCount{2}GetChars{3}};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Trace);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_4);$il.Emit([Reflection.Emit.OpCodes]::Newarr,[int]);foreach($i in 0..3){$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$i);switch($i){0{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$kind)}1{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2)}2{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3)}3{if($write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1)}}};$il.Emit([Reflection.Emit.OpCodes]::Stelem_I4)};$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[Collections.Generic.List[int[]]].GetMethod('Add'))
 $mode=$il.DeclareLocal([int]);$normal=$il.DefineLabel();$nonNegative=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields[$(if($write){'WriteMode'}else{'CountMode'})]);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$mode)
 if($write){$skip=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ble,$skip);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,42);$il.Emit($(if($abstract.Name -eq 'GetBytes'){[Reflection.Emit.OpCodes]::Stelem_I1}else{[Reflection.Emit.OpCodes]::Stelem_I2}));$il.MarkLabel($skip)}
 $il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'array callback failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($normal);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Multiplier);$il.Emit([Reflection.Emit.OpCodes]::Mul);$il.Emit([Reflection.Emit.OpCodes]::Ret)
 }else{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ret)};$builder.DefineMethodOverride($method,$abstract)}
function EncodingBridge([string]$Direction,[bool]$Write){
 $encoder=$Direction -eq 'Encoder';$owner=[Text.Encoding];$sourceElement=if($encoder){[char]}else{[byte]};$destinationElement=if($encoder){[byte]}else{[char]};$sourceArray=$sourceElement.MakeArrayType();$destinationArray=$destinationElement.MakeArrayType();$readOnly=[type]'System.ReadOnlySpan`1';$span=[type]'System.Span`1';$sourceType=$readOnly.MakeGenericType([type[]]@($sourceElement));$destinationType=$span.MakeGenericType([type[]]@($destinationElement))
 [type[]]$signature=if($Write){@($owner,$sourceArray,[int],[int],$destinationArray,[int],[int])}else{@($owner,$sourceArray,[int],[int])};$methodName=if($encoder){if($Write){'GetBytes'}else{'GetByteCount'}}else{if($Write){'GetChars'}else{'GetCharCount'}};[type[]]$methodSignature=if($Write){@($sourceType,$destinationType)}else{@($sourceType)};$method=$owner.GetMethod($methodName,$methodSignature)
 $bridge=[Reflection.Emit.DynamicMethod]::new('StatefulSpan'+$Direction+$Write,[int],$signature);$il=$bridge.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$sourceType.GetConstructor([type[]]@($sourceArray,[int],[int])))
 if($Write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$destinationType.GetConstructor([type[]]@($destinationArray,[int],[int])))};$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$definition=[type]('System.Func`'+($signature.Count+1));return $bridge.CreateDelegate($definition.MakeGenericType([type[]]@($signature+[int])))
}
function StateBridge([string]$Direction,[bool]$Write){
 $encoder=$Direction -eq 'Encoder';$owner=if($encoder){[Text.Encoder]}else{[Text.Decoder]};$sourceElement=if($encoder){[char]}else{[byte]};$destinationElement=if($encoder){[byte]}else{[char]};$sourceArray=$sourceElement.MakeArrayType();$destinationArray=$destinationElement.MakeArrayType();$readOnly=[type]'System.ReadOnlySpan`1';$span=[type]'System.Span`1';$sourceType=$readOnly.MakeGenericType([type[]]@($sourceElement));$destinationType=$span.MakeGenericType([type[]]@($destinationElement))
 [type[]]$signature=if($Write){@($owner,$sourceArray,[int],[int],$destinationArray,[int],[int],[bool])}else{@($owner,$sourceArray,[int],[int],[bool])};$methodName=if($encoder){if($Write){'GetBytes'}else{'GetByteCount'}}else{if($Write){'GetChars'}else{'GetCharCount'}};[type[]]$methodSignature=if($Write){@($sourceType,$destinationType,[bool])}else{@($sourceType,[bool])};$method=$owner.GetMethod($methodName,$methodSignature)
 $bridge=[Reflection.Emit.DynamicMethod]::new('StatefulSpan'+$Direction+$Write,[int],$signature);$il=$bridge.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$sourceType.GetConstructor([type[]]@($sourceArray,[int],[int])))
 if($Write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$destinationType.GetConstructor([type[]]@($destinationArray,[int],[int])));$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]7)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4)};$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$definition=[type]('System.Func`'+($signature.Count+1));return $bridge.CreateDelegate($definition.MakeGenericType([type[]]@($signature+[int])))
}

function Failure($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$type=$builder.CreateType();$bridges=@{};foreach($direction in @('Encoder','Decoder')){foreach($write in @($false,$true)){$bridges['Encoding'+$direction+$write]=EncodingBridge $direction $write;$bridges['State'+$direction+$write]=StateBridge $direction $write}};$rows=[Collections.Generic.List[object]]::new()
foreach($receiver in @('Encoding','State')){foreach($direction in @('Encoder','Decoder')){foreach($multiplier in @(1,3)){foreach($countMode in 0..2){foreach($writeMode in 0..2){foreach($length in @(0,1,3,7)){foreach($write in @($false,$true)){foreach($capacity in $(if($write){@(0,1,3,8)}else{@(0)})){foreach($offset in $(if($write){@(0,2)}else{@(0)})){foreach($flush in $(if($receiver -eq 'State'){@($false,$true)}else{@($false)})){$encoding=[Activator]::CreateInstance($type);foreach($pair in @(@('Multiplier',$multiplier),@('CountMode',$countMode),@('WriteMode',$writeMode))){$type.GetField($pair[0]).SetValue($encoding,[int]$pair[1])};$trace=[Collections.Generic.List[int[]]]::new();$type.GetField('Trace').SetValue($encoding,$trace);$state=if($receiver -eq 'Encoding'){$encoding}elseif($direction -eq 'Encoder'){$encoding.GetEncoder()}else{$encoding.GetDecoder()};$sourceValue=if($direction -eq 'Encoder'){,[char[]]::new($length+2)}else{,[byte[]]::new($length+2)};$target=if($direction -eq 'Encoder'){,[byte[]]::new($capacity+$offset+2)}else{,[char[]]::new($capacity+$offset+2)};for($i=0;$i -lt $target.Length;$i++){$target[$i]=99};$size=if($write){7}else{4};if($receiver -eq 'State'){$size++};$arguments=[object[]]::new($size);$arguments[0]=$state;$arguments[1]=$sourceValue;$arguments[2]=[int]1;$arguments[3]=[int]$length;if($write){$arguments[4]=$target;$arguments[5]=[int]$offset;$arguments[6]=[int]$capacity};if($receiver -eq 'State'){$arguments[$size-1]=[bool]$flush}
try{$n=$bridges[$receiver+$direction+$write].DynamicInvoke($arguments);$result=[ordered]@{ok=$true;count=$n}}catch{$result=Failure $_.Exception}
$rows.Add([ordered]@{receiver=$receiver;direction=$direction;multiplier=$multiplier;countMode=$countMode;writeMode=$writeMode;length=$length;write=$write;capacity=$capacity;offset=$offset;flush=$flush;result=$result;destination=[int[]]$target;trace=$trace.ToArray()})
}}}}}}}}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification='SELECTED_GENERIC_ENCODING_AND_DEFAULT_FACTORY_COUNT_WRITE_HEAP_SPANS_ONLY; ARBITRARY_POINTER_OVERRIDES_CLR_LIFETIME_REENTRANCY_FULL_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS generic Encoding/default factory spans: $($rows.Count) native cases"
